"""HTTP access to a Syncbox server (see syncbox-openapi.yaml)."""

from __future__ import annotations

import hashlib
import http.client
import json
import os
import socket
import time
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, BinaryIO, Callable, Iterator
from urllib.parse import quote, urlsplit

from .errors import ClientError

# Seconds to wait for a TCP connection to the server.
CONNECT_TIMEOUT = 10.0
# Seconds of silence on an open connection before giving up. Generous, as
# the server hashes every blob to answer GET /blobs.
READ_TIMEOUT = 120.0
# A keep-alive connection idle for longer than this is replaced rather than
# reused, so a server that has dropped it meanwhile doesn't fail the request.
_MAX_IDLE = 5.0

_CHUNK = 64 * 1024


class ServerError(ClientError):
    """The server could not be reached or gave an unusable answer."""


@dataclass(frozen=True)
class ServerURL:
    host: str
    port: int
    base_path: str  # "" or "/prefix", without a trailing slash
    text: str  # as given by the user, for messages


def parse_server_url(raw: str) -> ServerURL:
    """Parse ``http://host[:port][/prefix]``; raises ValueError if it isn't one."""
    problem = f"invalid server URL {raw!r}: expected http://host[:port]"
    parts = urlsplit(raw)
    scheme = parts.scheme.lower()
    if scheme == "https":
        raise ValueError(f"unsupported server URL {raw!r}: only http:// is supported")
    if scheme != "http":
        raise ValueError(problem)
    try:
        port = parts.port
    except ValueError:
        raise ValueError(f"{problem} (bad port)") from None
    if not parts.hostname or parts.username is not None or parts.query or parts.fragment:
        raise ValueError(problem)
    return ServerURL(
        host=parts.hostname,
        port=port or 80,
        base_path=parts.path.rstrip("/"),
        text=raw,
    )


@dataclass(frozen=True)
class RemoteBlob:
    key: str
    size: int
    sha256: str
    # None if the server didn't send a valid ISO 8601 time; only sync needs it.
    modified_at: datetime | None = None


def _parse_time(value: object) -> datetime | None:
    """An ISO 8601 time as an aware datetime (UTC if it has no offset), or None."""
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=timezone.utc)


def _parse_blob_list(body: bytes) -> list[RemoteBlob] | None:
    """The blobs listed in a GET /blobs response body, or None if it is malformed."""
    try:
        payload = json.loads(body)
    except ValueError:
        return None
    if not isinstance(payload, list):
        return None
    blobs = []
    for item in payload:
        if not (
            isinstance(item, dict)
            and isinstance(item.get("key"), str)
            and isinstance(item.get("sha256"), str)
            and isinstance(item.get("size"), int)
        ):
            return None
        blobs.append(RemoteBlob(
            key=item["key"],
            size=item["size"],
            sha256=item["sha256"],
            modified_at=_parse_time(item.get("modified_at")),
        ))
    return blobs


def _error_detail(status: int, reason: str, body: bytes) -> str:
    """``HTTP 400 Bad Request: <the server's error message, if any>``."""
    text = f"HTTP {status} {reason}".rstrip()
    try:
        message = json.loads(body).get("error")
    except (ValueError, AttributeError):
        message = None
    return f"{text}: {message}" if isinstance(message, str) and message else text


def _describe(exc: BaseException) -> str:
    if isinstance(exc, TimeoutError):
        return "timed out"
    if isinstance(exc, socket.gaierror):
        return f"cannot resolve host ({exc.strerror})"
    if isinstance(exc, OSError) and exc.strerror:
        return exc.strerror
    return str(exc) or type(exc).__name__


class _BodyError(Exception):
    """Reading the local file for a request body failed; the message says why."""


def _file_body(f: BinaryIO, size: int, digest: Any) -> Iterator[bytes]:
    """Exactly ``size`` bytes of ``f`` in chunks, fed to ``digest`` as they go.

    Raises _BodyError if the file turns out shorter or longer than ``size``.
    That happens before the last chunk is handed out, so the server never
    receives a complete body and keeps its old blob.
    """
    remaining = size
    try:
        while remaining > 0:
            chunk = f.read(min(_CHUNK, remaining))
            if not chunk:
                raise _BodyError("file shrank while it was being uploaded")
            remaining -= len(chunk)
            if remaining == 0 and f.read(1):
                raise _BodyError("file grew while it was being uploaded")
            digest.update(chunk)
            yield chunk
    except OSError as exc:
        raise _BodyError(_describe(exc)) from None


class _Connection(http.client.HTTPConnection):
    """Connects within CONNECT_TIMEOUT, then waits up to READ_TIMEOUT for data."""

    def connect(self) -> None:
        super().connect()
        self.sock.settimeout(READ_TIMEOUT)


class ServerClient:
    """Requests to one server over a reused (keep-alive) connection."""

    def __init__(self, url: ServerURL) -> None:
        self.url = url
        self._conn = _Connection(url.host, url.port, timeout=CONNECT_TIMEOUT)
        self._last_used = 0.0

    def close(self) -> None:
        self._conn.close()

    def __enter__(self) -> ServerClient:
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.close()

    def list_blobs(self) -> list[RemoteBlob]:
        status, reason, body = self._request("GET", "/blobs")
        if status != 200:
            raise ServerError(f"listing blobs failed: {_error_detail(status, reason, body)}")
        blobs = _parse_blob_list(body)
        if blobs is None:
            raise ServerError("listing blobs failed: malformed response from server")
        return blobs

    def put_blob(self, key: str, path: Path) -> str:
        """Upload the file at ``path`` as blob ``key``; returns the sha256 of the bytes sent.

        The file is read once, as it is sent, and the upload fails if the
        sha256 the server reports for the stored blob differs from that of
        the bytes sent.
        """
        try:
            # O_NONBLOCK: a file swapped for a FIFO since the scan can't block us.
            fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        except OSError as exc:
            raise ClientError(f"cannot read {key!r}: {_describe(exc)}") from None
        digest = hashlib.sha256()
        with open(fd, "rb") as f:
            size = os.fstat(fd).st_size
            try:
                status, reason, body = self._request(
                    "PUT",
                    "/blobs/" + quote(key, safe="/"),
                    body=_file_body(f, size, digest),
                    headers={
                        "Content-Length": str(size),
                        "Content-Type": "application/octet-stream",
                    },
                )
            except _BodyError as exc:
                raise ClientError(f"cannot upload {key!r}: {exc}") from None
        if status not in (200, 201):
            raise ServerError(f"cannot upload {key!r}: {_error_detail(status, reason, body)}")
        try:
            stored = json.loads(body).get("sha256")
        except (ValueError, AttributeError):
            stored = None
        if stored is not None and stored != digest.hexdigest():
            raise ServerError(
                f"cannot upload {key!r}: server stored sha256 {stored}, sent {digest.hexdigest()}"
            )
        return digest.hexdigest()

    def get_blob(self, key: str, size: int, sink: Callable[[bytes], object]) -> str | None:
        """Download blob ``key``, listed as ``size`` bytes long, handing it to ``sink`` in chunks.

        Returns the sha256 of the bytes received, or None if the server has
        no such blob. Raises ServerError if the server can't be reached,
        answers with an error, or sends other than ``size`` bytes; part of
        the body may have gone to ``sink`` by then. Exceptions raised by
        ``sink`` propagate.
        """
        resp = self._send("GET", "/blobs/" + quote(key, safe="/"))
        digest = hashlib.sha256()
        try:
            if resp.status != 200:
                body = self._read_body(resp, key)
                if resp.status == 404:
                    return None
                raise ServerError(f"cannot download {key!r}: {_error_detail(resp.status, resp.reason, body)}")
            if resp.length is not None and resp.length != size:
                raise ServerError(f"cannot download {key!r}: server sent {resp.length} bytes, listed {size}")
            received = 0
            # Up to one byte more than listed is asked for, to notice a body that is too long.
            while chunk := self._read_body(resp, key, min(_CHUNK, size - received + 1)):
                received += len(chunk)
                if received > size:
                    raise ServerError(f"cannot download {key!r}: server sent more than the {size} bytes listed")
                digest.update(chunk)
                sink(chunk)
            if received != size:
                raise ServerError(f"cannot download {key!r}: body ended after {received} of {size} bytes")
        except BaseException:
            self._conn.close()
            raise
        self._last_used = time.monotonic()
        return digest.hexdigest()

    @staticmethod
    def _read_body(resp: http.client.HTTPResponse, key: str, amount: int | None = None) -> bytes:
        try:
            return resp.read(amount)
        except (OSError, http.client.HTTPException) as exc:
            raise ServerError(f"cannot download {key!r}: {_describe(exc)}") from None

    def _request(
        self,
        method: str,
        path: str,
        body: bytes | Iterator[bytes] | None = None,
        headers: dict[str, str] | None = None,
    ) -> tuple[int, str, bytes]:
        """Send a request; returns (status, reason, response body).

        Raises ServerError if the server can't be reached or the exchange
        breaks off. Exceptions raised by ``body`` propagate. Either way the
        connection is closed; the next request reopens it.
        """
        resp = self._send(method, path, body, headers)
        try:
            data = resp.read()
        except (OSError, http.client.HTTPException) as exc:
            self._conn.close()
            raise ServerError(f"cannot reach server {self.url.text}: {_describe(exc)}") from None
        except BaseException:
            self._conn.close()
            raise
        self._last_used = time.monotonic()
        return resp.status, resp.reason, data

    def _send(
        self,
        method: str,
        path: str,
        body: bytes | Iterator[bytes] | None = None,
        headers: dict[str, str] | None = None,
    ) -> http.client.HTTPResponse:
        """Send a request and read the response head; the caller reads the body.

        Raises as _request() does.
        """
        if time.monotonic() - self._last_used > _MAX_IDLE:
            self._conn.close()
        try:
            self._conn.request(method, self.url.base_path + path, body=body, headers=headers or {})
            return self._conn.getresponse()
        except (OSError, http.client.HTTPException) as exc:
            self._conn.close()
            raise ServerError(f"cannot reach server {self.url.text}: {_describe(exc)}") from None
        except BaseException:
            self._conn.close()
            raise
"""Command line: ``syncbox <push|pull|sync|status> <dir> --server <url>``.

``--server`` falls back to the SYNCBOX_SERVER environment variable (the flag
wins; an empty variable counts as unset). Exit codes: 0 on success (for
status, whether or not anything differs), 1 if the command failed, 2 on a
usage error. sync keeps its state between runs outside ``<dir>`` (see
state.py for where).
"""

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path
from typing import Mapping, Sequence

from .api import ServerClient, parse_server_url
from .errors import ClientError
from .pull import pull
from .push import push
from .state import SyncState
from .status import StatusResult, status
from .sync import SyncResult, sync

ENV_SERVER = "SYNCBOX_SERVER"

EXIT_OK = 0
EXIT_FAILURE = 1
EXIT_USAGE = 2

COMMANDS = {
    "push": "upload files that are missing or different on the server",
    "pull": "download files that are missing or different locally",
    "sync": "push and pull; on conflict the newer version wins",
    "status": "show what push/pull would transfer, changing nothing",
}


def _error(message: str) -> None:
    print(f"syncbox: error: {message}", file=sys.stderr, flush=True)


def _warn(message: str) -> None:
    print(f"syncbox: warning: {message}", file=sys.stderr, flush=True)


def _report(line: str) -> None:
    print(line, flush=True)


def _status_summary(result: StatusResult) -> str:
    unchanged = len(result.unchanged)
    if not result.upload and not result.download:
        return f"nothing to upload or download, {unchanged} up to date"
    return f"{len(result.upload)} to upload, {len(result.download)} to download, {unchanged} up to date"


def _sync_summary(result: SyncResult) -> str:
    summary = (
        f"{len(result.uploaded)} uploaded, {len(result.downloaded)} downloaded,"
        f" {len(result.unchanged)} already up to date"
    )
    conflicts = len(result.conflicts)
    if conflicts:
        summary += f" ({conflicts} conflict{'s' if conflicts > 1 else ''} resolved)"
    return summary


def _sync(root: Path, client: ServerClient, env: Mapping[str, str]) -> SyncResult:
    """Run sync() with the state recorded for ``root`` and the server, and record the new one."""
    sync_state = SyncState.for_dir(root, client.url, env)
    previous = sync_state.load(_warn)
    state = dict(previous)
    try:
        return sync(root, client, state, report=_report, warn=_warn)
    finally:
        # Also after a failure: the files synced so far are recorded.
        if state != previous:
            sync_state.save(state, _warn)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="syncbox", description="Syncbox client.")
    commands = parser.add_subparsers(dest="command", metavar="<command>", required=True)
    for name, summary in COMMANDS.items():
        command = commands.add_parser(name, help=summary, description=summary)
        command.add_argument("dir", metavar="<dir>", help="local directory")
        command.add_argument(
            "--server",
            metavar="<url>",
            help=f"server URL, e.g. http://127.0.0.1:8080 (env: {ENV_SERVER}; required)",
        )
    return parser


def main(argv: Sequence[str] | None = None, environ: Mapping[str, str] | None = None) -> int:
    env = os.environ if environ is None else environ
    args = build_parser().parse_args(argv)  # exits with EXIT_USAGE on bad arguments

    raw_server = args.server if args.server is not None else env.get(ENV_SERVER) or None
    if not raw_server:
        _error(f"server URL is required: pass --server or set {ENV_SERVER}")
        return EXIT_USAGE
    try:
        server = parse_server_url(raw_server)
    except ValueError as exc:
        _error(str(exc))
        return EXIT_USAGE

    root = Path(args.dir)
    if not root.is_dir():
        problem = "is not a directory" if root.exists() else "does not exist"
        _error(f"{args.dir!r} {problem}")
        return EXIT_FAILURE

    try:
        with ServerClient(server) as client:
            if args.command == "push":
                pushed = push(root, client, report=_report, warn=_warn)
                summary = f"{len(pushed.uploaded)} uploaded, {len(pushed.unchanged)} already up to date"
            elif args.command == "pull":
                pulled = pull(root, client, report=_report, warn=_warn)
                summary = f"{len(pulled.downloaded)} downloaded, {len(pulled.unchanged)} already up to date"
            elif args.command == "sync":
                summary = _sync_summary(_sync(root, client, env))
            else:
                summary = _status_summary(status(root, client, report=_report, warn=_warn))
    except ClientError as exc:
        _error(str(exc))
        return EXIT_FAILURE
    except KeyboardInterrupt:
        _error("interrupted")
        return 130
    _report(summary)
    return EXIT_OK
"""Errors the client reports to the user."""

from __future__ import annotations


class ClientError(Exception):
    """A command failed; the message is meant for the user."""
"""The local side of a sync: files under a directory and their hashes.

A file's key is its path relative to the directory, with ``/`` separators
(``docs/readme.txt``) — the same convention the server uses for blob keys.

Only regular files are synced. Symbolic links (to files or directories) and
special files (FIFOs, sockets, devices) are skipped with a warning rather
than followed: a link may point outside the directory, and a FIFO would
block the read.
"""

from __future__ import annotations

import hashlib
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Callable

from .errors import ClientError


@dataclass(frozen=True)
class LocalFile:
    key: str
    path: Path
    sha256: str


def _describe_error(exc: OSError) -> str:
    return exc.strerror or str(exc)


def key_for(rel_path: str) -> str:
    """The blob key for a ``/``-separated path relative to the directory.

    Raises ClientError if the path can't be a key: names that are not valid
    UTF-8 reach Python as lone surrogates and can't be sent to the server.
    """
    try:
        rel_path.encode("utf-8")
    except UnicodeEncodeError:
        shown = os.fsencode(rel_path).decode("utf-8", "backslashreplace")
        raise ClientError(f"cannot sync '{shown}': file name is not valid UTF-8") from None
    return rel_path


def find_files(root: Path, warn: Callable[[str], None]) -> list[tuple[str, Path]]:
    """``(key, path)`` of every regular file under ``root``, sorted by key."""
    found: list[tuple[str, Path]] = []
    # (directory, its key prefix); an explicit stack, as trees can be deeper
    # than Python's recursion limit.
    pending: list[tuple[Path, str]] = [(root, "")]
    while pending:
        directory, prefix = pending.pop()
        try:
            with os.scandir(directory) as it:
                entries = list(it)
        except OSError as exc:
            where = repr(prefix.rstrip("/")) if prefix else str(root)
            raise ClientError(f"cannot read directory {where}: {_describe_error(exc)}") from None
        for entry in entries:
            rel = prefix + entry.name
            try:
                if entry.is_symlink():
                    warn(f"skipping {rel!r}: symbolic link")
                elif entry.is_dir(follow_symlinks=False):
                    pending.append((Path(entry.path), rel + "/"))
                elif entry.is_file(follow_symlinks=False):
                    found.append((key_for(rel), Path(entry.path)))
                else:
                    warn(f"skipping {rel!r}: not a regular file")
            except OSError as exc:
                raise ClientError(f"cannot read {rel!r}: {_describe_error(exc)}") from None
    found.sort()
    return found


def file_sha256(key: str, path: Path | str, dir_fd: int | None = None) -> str:
    """SHA-256 of the file at ``path`` (relative to ``dir_fd``, if given), not following a symlink."""
    try:
        # O_NONBLOCK: a file swapped for a FIFO since the scan can't block us.
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=dir_fd)
        with open(fd, "rb") as f:
            return hashlib.file_digest(f, "sha256").hexdigest()
    except OSError as exc:
        raise ClientError(f"cannot read {key!r}: {_describe_error(exc)}") from None


def scan(root: Path, warn: Callable[[str], None]) -> list[LocalFile]:
    """Every regular file under ``root`` with its SHA-256, sorted by key."""
    return [LocalFile(key, path, file_sha256(key, path)) for key, path in find_files(root, warn)]
"""``syncbox pull``: download blobs that are missing locally or differ from the local file.

Blob keys come from the server and are not trusted: a key must be a relative
path of plain names (no ``..``, ``.``, empty or absolute components), and
the path is walked one directory at a time from ``<dir>`` without following
symbolic links, so neither a key nor a symlink inside ``<dir>`` can lead a
write outside it. As with push, symlinks and special files are not synced:
a key that leads to one is skipped with a warning.

A file is written to a temporary file in its directory, checked against the
SHA-256 the server listed and then renamed over the old version, so the
local file is always either the old version or the complete new one.
"""

from __future__ import annotations

import errno
import os
import secrets
import stat
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable

from .api import RemoteBlob, ServerClient, ServerError
from .errors import ClientError
from .local import file_sha256

# O_PATH: walking through a directory needs no read permission on it.
# O_NOFOLLOW: a symlink in place of a directory is not followed (open fails).
_DIR_FLAGS = os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
_TMP_FLAGS = os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC


@dataclass
class PullResult:
    downloaded: list[str] = field(default_factory=list)
    unchanged: list[str] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)


class Skip(Exception):
    """The blob is left alone; the message says why."""


def is_safe_key(key: str) -> bool:
    """Whether ``key`` is a relative POSIX path of plain names that can be a local file name."""
    if not key or "\0" in key:
        return False
    try:
        key.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return all(part not in ("", ".", "..") for part in key.split("/"))


def _describe(exc: OSError) -> str:
    return exc.strerror or str(exc)


def pull(
    root: Path,
    client: ServerClient,
    report: Callable[[str], None],
    warn: Callable[[str], None],
) -> PullResult:
    """Download every blob whose SHA-256 differs from the file under ``root`` at its key.

    Files that already have the server's content are not downloaded again;
    local files with no blob are left alone. Calls ``report`` with a line
    per downloaded file and ``warn`` per skipped blob. Stops at the first
    failure (raising ClientError).
    """
    blobs = client.list_blobs()
    for blob in blobs:
        if not is_safe_key(blob.key):
            raise ClientError(f"server listed an invalid key {blob.key!r}; nothing was downloaded")
    root_fd = open_root(root)
    result = PullResult()
    try:
        for blob in blobs:
            try:
                outcome = pull_blob(root_fd, blob, client)
            except Skip as skip:
                warn(f"skipping {blob.key!r}: {skip}")
                result.skipped.append(blob.key)
                continue
            if outcome is None:
                result.unchanged.append(blob.key)
            else:
                result.downloaded.append(blob.key)
                report(f"{outcome} {blob.key}")
    finally:
        os.close(root_fd)
    return result


def open_root(root: Path) -> int:
    """A descriptor of ``root`` for pull_blob(); the caller closes it."""
    try:
        return os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC)
    except OSError as exc:
        raise ClientError(f"cannot open directory {str(root)!r}: {_describe(exc)}") from None


# pull_blob(replacing=ANY_FILE): whatever is at the key gets replaced.
ANY_FILE = object()


def pull_blob(root_fd: int, blob: RemoteBlob, client: ServerClient, replacing: object = ANY_FILE) -> str | None:
    """Bring the file at ``blob.key`` up to date: "added", "updated", or None if it already was.

    ``replacing`` is the SHA-256 the local file must still have to be
    replaced, or None if there must be no file: a file that differs from
    it (changed since it was looked at) is skipped rather than overwritten.
    A file that has vanished meanwhile is downloaded all the same.
    """
    *dirs, name = blob.key.split("/")
    parent_fd = _open_parent(root_fd, dirs, blob.key, create=False)
    existing = None
    try:
        if parent_fd is not None:
            existing = _existing_file(parent_fd, name, blob.key)
            if existing is not None and replacing is ANY_FILE:
                if existing.st_size == blob.size and file_sha256(blob.key, name, dir_fd=parent_fd) == blob.sha256:
                    return None
            elif existing is not None:
                current = file_sha256(blob.key, name, dir_fd=parent_fd)
                if current == blob.sha256:
                    return None
                if current != replacing:
                    raise Skip("changed locally during the sync")
        else:
            parent_fd = _open_parent(root_fd, dirs, blob.key, create=True)
        _download(client, blob, parent_fd, name, None if existing is None else existing.st_mode)
    finally:
        if parent_fd is not None:
            os.close(parent_fd)
    return "added" if existing is None else "updated"


def _open_parent(root_fd: int, dirs: list[str], key: str, create: bool) -> int | None:
    """A descriptor of the directory ``dirs`` under ``root_fd``, walked without following symlinks.

    Missing directories are created if ``create`` is set; otherwise None is
    returned for a directory that doesn't exist.
    """
    fd = os.dup(root_fd)
    for depth, name in enumerate(dirs, 1):
        try:
            child = _open_dir(fd, name, create)
        except OSError as exc:
            where = "/".join(dirs[:depth])
            if exc.errno in (errno.ELOOP, errno.ENOTDIR):
                if _is_symlink(fd, name):
                    raise Skip(f"{where!r} is a symbolic link") from None
