        key.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return all(part not in ("", ".", "..") for part in key.split("/"))


def _describe(exc: OSError) -> str:
    return exc.strerror or str(exc)


def pull(
    root: Path,
    client: ServerClient,
    report: Callable[[str], None],
    warn: Callable[[str], None],
) -> PullResult:
    """Download every blob whose SHA-256 differs from the file under ``root`` at its key.

    Files that already have the server's content are not downloaded again;
    local files with no blob are left alone. Calls ``report`` with a line
    per downloaded file and ``warn`` per skipped blob. Stops at the first
    failure (raising ClientError).
    """
    blobs = client.list_blobs()
    for blob in blobs:
        if not is_safe_key(blob.key):
            raise ClientError(f"server listed an invalid key {blob.key!r}; nothing was downloaded")
    root_fd = open_root(root)
    result = PullResult()
    try:
        for blob in blobs:
            try:
                outcome = pull_blob(root_fd, blob, client)
            except Skip as skip:
                warn(f"skipping {blob.key!r}: {skip}")
                result.skipped.append(blob.key)
                continue
            if outcome is None:
                result.unchanged.append(blob.key)
            else:
                result.downloaded.append(blob.key)
                report(f"{outcome} {blob.key}")
    finally:
        os.close(root_fd)
    return result


def open_root(root: Path) -> int:
    """A descriptor of ``root`` for pull_blob(); the caller closes it."""
    try:
        return os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC)
    except OSError as exc:
        raise ClientError(f"cannot open directory {str(root)!r}: {_describe(exc)}") from None


# pull_blob(replacing=ANY_FILE): whatever is at the key gets replaced.
ANY_FILE = object()


def pull_blob(root_fd: int, blob: RemoteBlob, client: ServerClient, replacing: object = ANY_FILE) -> str | None:
    """Bring the file at ``blob.key`` up to date: "added", "updated", or None if it already was.

    ``replacing`` is the SHA-256 the local file must still have to be
    replaced, or None if there must be no file: a file that differs from
    it (changed since it was looked at) is skipped rather than overwritten.
    A file that has vanished meanwhile is downloaded all the same.
    """
    *dirs, name = blob.key.split("/")
    parent_fd = _open_parent(root_fd, dirs, blob.key, create=False)
    existing = None
    try:
        if parent_fd is not None:
            existing = _existing_file(parent_fd, name, blob.key)
            if existing is not None and replacing is ANY_FILE:
                if existing.st_size == blob.size and file_sha256(blob.key, name, dir_fd=parent_fd) == blob.sha256:
                    return None
            elif existing is not None:
                current = file_sha256(blob.key, name, dir_fd=parent_fd)
                if current == blob.sha256:
                    return None
                if current != replacing:
                    raise Skip("changed locally during the sync")
        else:
            parent_fd = _open_parent(root_fd, dirs, blob.key, create=True)
        _download(client, blob, parent_fd, name, None if existing is None else existing.st_mode)
    finally:
        if parent_fd is not None:
            os.close(parent_fd)
    return "added" if existing is None else "updated"


