"""``syncbox sync``: push and pull in one pass, resolving conflicts by modification time.

Files are matched by key and compared by SHA-256, as push and pull compare
them. For a file that differs between ``<dir>`` and the server:

- present on one side only: it is copied to the other (uploaded or
  downloaded). Nothing is ever deleted, on either side: a file deleted on
  one side comes back from the other.
- present on both, and one side still has the content recorded at the last
  sync (see state.py): only the other side changed it, so that version is
  copied over.
- present on both, and neither side has the recorded content (a conflict:
  both changed it since): the version with the later modification time —
  the local file's mtime or the blob's ``modified_at`` — wins; on a tie the
  local version does.
- present on both with no recorded content at all (the first sync, or a
  file created on both sides since): neither side is known to be
  unchanged, so the same rule decides.

Downloads are written as pull writes them, and a local file that changes
between being hashed and being replaced is skipped rather than overwritten.
"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable

from .api import RemoteBlob, ServerClient
from .errors import ClientError
from .local import LocalFile, scan
from .pull import Skip, is_safe_key, open_root, pull_blob


@dataclass
class SyncResult:
    uploaded: list[str] = field(default_factory=list)
    downloaded: list[str] = field(default_factory=list)
    unchanged: list[str] = field(default_factory=list)
    conflicts: list[str] = field(default_factory=list)  # also in uploaded or downloaded
    skipped: list[str] = field(default_factory=list)


@dataclass(frozen=True)
class _Plan:
    upload: bool  # else download
    kind: str  # "new", "changed", "conflict" or "differs"
    note: str = ""


def sync(
    root: Path,
    client: ServerClient,
    state: dict[str, str],
    report: Callable[[str], None],
    warn: Callable[[str], None],
) -> SyncResult:
    """Bring ``root`` and the server to the same content.

    ``state`` is ``{key: sha256}`` as of the last sync; it is updated in
    place as files are found or made equal on both sides, so that it can be
    saved even if the sync stops part way. Calls ``report`` with a line per
    transferred file and ``warn`` per skipped one. Stops at the first
    failure (raising ClientError).
    """
    # The server is asked first, so an unreachable one fails before the
    # whole tree has been hashed.
    remote: dict[str, RemoteBlob] = {}
    for blob in client.list_blobs():
        if is_safe_key(blob.key):
            remote[blob.key] = blob
        else:
            warn(f"skipping {blob.key!r}: not a valid key for a local file")
    local = {file.key: file for file in scan(root, warn)}

    for key in [key for key in state if key not in local and key not in remote]:
        del state[key]

    result = SyncResult()
    root_fd = open_root(root)
    try:
        for key in sorted(local.keys() | remote.keys()):
            file, blob = local.get(key), remote.get(key)
            if file is not None and blob is not None and file.sha256 == blob.sha256:
                state[key] = file.sha256
                result.unchanged.append(key)
                continue
            plan = _plan(file, blob, state.get(key))
            try:
                if plan.upload:
                    assert file is not None
                    state[key] = client.put_blob(key, file.path)
                    result.uploaded.append(key)
                else:
                    assert blob is not None
                    if pull_blob(root_fd, blob, client, None if file is None else file.sha256) is None:
                        # Changed locally to the server's version meanwhile.
                        state[key] = blob.sha256
                        result.unchanged.append(key)
                        continue
                    state[key] = blob.sha256
                    result.downloaded.append(key)
            except Skip as skip:
                warn(f"skipping {key!r}: {skip}")
                result.skipped.append(key)
                continue
            if plan.kind == "conflict":
                result.conflicts.append(key)
            line = f"{'upload' if plan.upload else 'download':<8}  {plan.kind:<8}  {key}"
            report(f"{line}  ({plan.note})" if plan.note else line)
    finally:
        os.close(root_fd)
    return result


def _plan(file: LocalFile | None, blob: RemoteBlob | None, synced: str | None) -> _Plan:
    """Which way a file that differs between the sides goes; ``synced`` is its hash at the last sync."""
    if blob is None:
        return _Plan(upload=True, kind="new")
    if file is None:
        return _Plan(upload=False, kind="new")
    if synced == file.sha256:
        return _Plan(upload=False, kind="changed")
    if synced == blob.sha256:
        return _Plan(upload=True, kind="changed")
    local_time = _local_mtime(file)
    if blob.modified_at is None:
        raise ClientError(f"cannot sync {file.key!r}: the server did not report when it was modified")
    if local_time == blob.modified_at:
        upload, note = True, "same modification time, local wins"
    else:
        upload = local_time > blob.modified_at
        note = "local is newer" if upload else "server is newer"
    if synced is None:
        return _Plan(upload, kind="differs", note=f"no common version known; {note}")
    return _Plan(upload, kind="conflict", note=note)


def _local_mtime(file: LocalFile) -> datetime:
    """The file's mtime, at the microsecond precision of the server's ``modified_at``."""
    try:
        st = os.lstat(file.path)
    except OSError as exc:
        raise ClientError(f"cannot read {file.key!r}: {exc.strerror or exc}") from None
    # The same conversion the server applies to a blob's mtime.
    return datetime.fromtimestamp(st.st_mtime, tz=timezone.utc)
"""``syncbox status``: show what push and pull would transfer, changing nothing.

The server is only asked for its list of blobs (GET /blobs), and files under
``<dir>`` are only read, to hash them, so neither side is changed. Files are
compared as push and pull compare them: by key and SHA-256, so a file whose
content differs on the two sides is listed in both directions.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable

from .api import ServerClient
from .local import scan
from .pull import is_safe_key


@dataclass(frozen=True)
class Change:
    key: str
    new: bool  # missing on the receiving side, rather than different there


@dataclass
class StatusResult:
    upload: list[Change] = field(default_factory=list)
    download: list[Change] = field(default_factory=list)
    unchanged: list[str] = field(default_factory=list)


def status(
    root: Path,
    client: ServerClient,
    report: Callable[[str], None],
    warn: Callable[[str], None],
) -> StatusResult:
    """Compare the files under ``root`` with the blobs on the server.

    Calls ``report`` with a line per file that push would upload, then per
    file that pull would download: ``upload new <key>`` for a file the
    server lacks, ``upload changed <key>`` for one it has another version
    of, and ``download new|changed <key>`` alike. Stops at the first
    failure (raising ClientError).
    """
    # The server is asked first, so an unreachable one fails before the
    # whole tree has been hashed.
    remote: dict[str, str] = {}
    for blob in client.list_blobs():
        if is_safe_key(blob.key):
            remote[blob.key] = blob.sha256
        else:
            warn(f"server lists an invalid key {blob.key!r}; pull would refuse to download it")
    local = {file.key: file.sha256 for file in scan(root, warn)}

    result = StatusResult()
    for key, sha256 in local.items():
        if remote.get(key) == sha256:
            result.unchanged.append(key)
        else:
            result.upload.append(Change(key, new=key not in remote))
    for key in sorted(remote):
        if local.get(key) != remote[key]:
            result.download.append(Change(key, new=key not in local))

    for direction, changes in (("upload", result.upload), ("download", result.download)):
        for change in changes:
            report(f"{direction:<8}  {'new' if change.new else 'changed':<7}  {change.key}")
    return result
"""What ``sync`` last saw both sides agree on, kept between runs.

For each pair of a local directory and a server there is a state file: the
SHA-256 of every file that, as of the last sync, had the same content
locally and on the server. That is the "last known common state" the
conflict rule compares against: a side whose file still has the recorded
hash hasn't changed it since.

State files live outside the synced directory, so they are never synced
themselves nor seen by anything comparing the directory with the server:
in SYNCBOX_STATE_DIR if set, else ``$XDG_STATE_HOME/syncbox``, else
``~/.local/state/syncbox``. The directory is identified by its real path,
or by SYNCBOX_DIR_ID if set (run-client sets it to the host path, as inside
the container the directory is always at the same mount point).

A state file is only a record; losing it costs nothing but conflict
detection on the next run. So a missing, unreadable or malformed one is
treated as empty (with a warning, unless it's merely missing), and a
failure to save one is a warning, not an error.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import secrets
from pathlib import Path
from typing import Callable, Mapping

from .api import ServerURL
from .errors import ClientError

ENV_STATE_DIR = "SYNCBOX_STATE_DIR"
ENV_DIR_ID = "SYNCBOX_DIR_ID"

_VERSION = 1
_SHA256 = re.compile(r"[0-9a-f]{64}")


def state_dir(env: Mapping[str, str]) -> Path:
    """Where state files are kept, per the environment."""
    if env.get(ENV_STATE_DIR):
        return Path(env[ENV_STATE_DIR])
    xdg = env.get("XDG_STATE_HOME")
    if xdg and os.path.isabs(xdg):
        return Path(xdg, "syncbox")
    home = env.get("HOME") or os.path.expanduser("~")
    if not os.path.isabs(home):
        raise ClientError(f"cannot tell where to keep the sync state: set {ENV_STATE_DIR}")
    return Path(home, ".local", "state", "syncbox")


class SyncState:
    """The state file of one directory and server."""

    def __init__(self, directory: Path, dir_id: str, server: ServerURL) -> None:
        self.dir_id = dir_id
        self.server = f"http://{server.host.lower()}:{server.port}{server.base_path}"
        name = hashlib.sha256(f"{self.dir_id}\0{self.server}".encode("utf-8", "surrogateescape")).hexdigest()
        self.path = directory / f"{name[:32]}.json"

    @classmethod
    def for_dir(cls, root: Path, server: ServerURL, env: Mapping[str, str]) -> SyncState:
        return cls(state_dir(env), env.get(ENV_DIR_ID) or os.path.realpath(root), server)

    def load(self, warn: Callable[[str], None]) -> dict[str, str]:
        """``{key: sha256}`` as of the last sync; empty if there was none."""
        try:
            payload = json.loads(self.path.read_bytes())
        except FileNotFoundError:
            return {}
        except OSError as exc:
            warn(f"cannot read sync state {str(self.path)!r}: {exc.strerror or exc}; treating every file as new")
            return {}
        except ValueError:
            payload = None
        files = payload.get("files") if isinstance(payload, dict) and payload.get("version") == _VERSION else None
        if (
            not isinstance(files, dict)
            or payload.get("dir") != self.dir_id
            or payload.get("server") != self.server
            or not all(isinstance(k, str) and isinstance(v, str) and _SHA256.fullmatch(v) for k, v in files.items())
        ):
            warn(f"ignoring malformed sync state {str(self.path)!r}; treating every file as new")
            return {}
        return files

    def save(self, files: Mapping[str, str], warn: Callable[[str], None]) -> None:
        """Record ``{key: sha256}`` as the state for the next sync, replacing the file atomically."""
        payload = {"version": _VERSION, "dir": self.dir_id, "server": self.server, "files": dict(sorted(files.items()))}
        data = json.dumps(payload, indent=1, ensure_ascii=True).encode() + b"\n"
        tmp = self.path.with_name(f".{self.path.stem}-{secrets.token_hex(8)}.tmp")
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC, 0o600)
            try:
                with open(fd, "wb") as f:
                    f.write(data)
                    f.flush()
                    os.fsync(fd)
                os.replace(tmp, self.path)
            finally:
                tmp.unlink(missing_ok=True)
        except OSError as exc:
            warn(
                f"cannot save sync state {str(self.path)!r}: {exc.strerror or exc};"
                " the next sync will compare against the previous state"
            )

